import Foundation

// Reach conventions used in this file (so a navigator can map them):
//   .tab("Home" | "Live TV" | "Movies" | "Series" | "TV Guide")   Mac: AppTab.rawValue.
//   .tab("home" | "live" | "guide" | "movies" | "series" | "search" | "library" | "playlists" | "settings" | "more")   iPhone/iPad: PhoneTab case name (IOSRouter.Tab).
//   .shortcut("discover" | "continueWatching" | ...)   Mac: Shortcut.rawValue (the sidebar lists of a tab).
//   .destination("channelManager" | "playlists" | ...)   Mac: Destination case name (AppRouter.go).
//   .modal("playlists" | "addPlaylist" | "about" | "channelManager" | "unlockRestricted")   Mac: ModalRoute case name. iPhone/iPad sheets: "ios.addPlaylist", "ios.multiView", "ios.player", "ios.detail".
//   .settingsPage("General" | "Appearance" | "Playback" | "Library" | "Privacy" | "Advanced")   Mac: SettingsTab.rawValue. A group inside a tab reaches its tab.
//   .settingsPage("playback" | "health" | "appearance" | "parental" | "privacyReport" | "library" | "artwork" | "channels" | "alerts" | "profiles" | "icloud" | "lan" | "proxy" | "appDNS" | "vpn" | "backup" | "storage" | "about")   iOS: SettingsPage.rawValue.
//   .window("main" | "player" | "feedback" | "files" | "shortcuts" | "multiview")   Mac: ReddyApp window ids.
//   .searchCommand("downloads" | "favorites" | ...)   CommandTarget.rawValue, used for list screens that have one.
//   .none   a screen reached only by opening an item (title, person, season, folder) or inside another screen.
// Ids: screen.tab.* and screen.shortcut.* replace the imported entries of the same id. screen.ios.* is iPhone and iPad only. screen.settings.<tab>.<group> is a block inside a Mac Settings tab.
enum AtlasScreens {
    private static let phone: AtlasPlatforms = [.iPhone, .iPad]

    private static func e(_ id: String, _ title: String, _ summary: String, _ path: [String], _ reach: AtlasReach = .none, _ aliases: [String] = [], kind: AtlasKind = .screen, detail: String? = nil,
                          shortcut: String? = nil, related: [String] = [], platforms: AtlasPlatforms = .mac, safety: AtlasSafety = .read, guideOnly: Bool = false, reviewed: Bool = false) -> AtlasEntry {
        .make(id, kind, title, summary, path: path, reach: reach, aliases: aliases, detail: detail, platforms: platforms, shortcut: shortcut, related: related, safety: safety, guideOnly: guideOnly, reviewed: reviewed)
    }
    /// A block inside a Mac Settings tab.
    private static func g(_ tab: String, _ key: String, _ title: String, _ summary: String, _ aliases: [String] = [], detail: String? = nil, related: [String] = [], safety: AtlasSafety = .read, guideOnly: Bool = false, reviewed: Bool = false) -> AtlasEntry {
        // A few blocks keep the id the question bank uses, and are shown on every platform because the phone has the same feature.
        let bank: [String: String] = ["parental": "screen.settings.parental", "profiles": "screen.settings.profiles", "privacyReport": "screen.settings.privacyReport", "artwork": "screen.settings.artwork", "guideAlerts": "screen.settings.keywordAlerts"]
        return e(bank[key] ?? "screen.settings.\(tab.lowercased()).\(key)", title, summary, ["Settings", tab, title], .settingsPage(tab), aliases, kind: .control, detail: detail, related: related, platforms: bank[key] != nil ? .all : .mac, safety: safety, guideOnly: guideOnly, reviewed: reviewed)
    }
    /// An iPhone or iPad page of Settings.
    private static func p(_ raw: String, _ id: String, _ title: String, _ summary: String, _ aliases: [String] = [], detail: String? = nil, related: [String] = [], safety: AtlasSafety = .read, guideOnly: Bool = false, reviewed: Bool = false) -> AtlasEntry {
        e(id, title, summary, ["Library", "Settings", title], .settingsPage(raw), aliases, kind: .settingsPage, detail: detail, related: related, platforms: phone, safety: safety, guideOnly: guideOnly, reviewed: reviewed)
    }

    static let all: [AtlasEntry] = tabs + sidebar + destinations + windows + settingsTabs + settingsGroups + macScreens + iosTabs + iosSettings + iosScreens + bankScreens

